var Utils = require("./utils")

module.exports = (function () {
    var ControllerFactory = function (name, options) {
        this.options = Utils._.extend({
            classMethods: {}
        }, options || {})

        this.name = name

        if (typeof this.options.defaultScope === "object") {
            Utils.injectScope.call(this, this.options.defaultScope)
        }

        addOptionalClassMethods.call(this)
    }

    var addOptionalClassMethods = function () {
        var self = this
        Utils._.each(this.options.classMethods || {}, function (fct, name) {
            self[name] = fct
        })
    }

    return ControllerFactory
})()